188	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
189	  sword: 1000,
190	  amulet: 600,
191	  rune: 250,
192	};
193	
194	const DEDUCTIBLE = 100;
195	const CAP_FACTOR = 2;
196	
197	const itemInsuranceValueOf = (item: Item): number =>
198	  INSURANCE_VALUE_BY_ITEM_TYPE[item.type];
199	
200	const MASTER_ENCHANTMENT_THRESHOLD = 8;
201	const MASTER_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
202	const FULL_REIMBURSEMENT_RATE = 1;
203	
204	const isMasterEnchanted = (item: Item): boolean =>
205	  (item.enchantment ?? 0) >= MASTER_ENCHANTMENT_THRESHOLD;
206	
207	// Dragon material needs no branch of its own: it is reimbursed in full, which
208	// is already the default rate. Master enchantment overrides that default.
209	const reimbursementRateOf = (item: Item): number =>
210	  isMasterEnchanted(item)
211	    ? MASTER_ENCHANTMENT_REIMBURSEMENT_RATE
212	    : FULL_REIMBURSEMENT_RATE;
213	
214	// A damage entry names an item type, not a particular item, so the terms that
215	// govern it come from an insured item of that type.
216	const insuredItemOfType = (
217	  itemType: string,
218	  insuredItems: readonly Item[],
219	): Item => insuredItems.find((item) => item.type === itemType) as Item;
220	
221	const damagePayoutOf = (damage: Damage, insuredItems: readonly Item[]): number =>
222	  damage.amount *
223	    reimbursementRateOf(insuredItemOfType(damage.itemType, insuredItems)) -
224	  DEDUCTIBLE;
225	
226	// The cap is twice the policy's insurance sum: the unmodified insurance values
227	// of the insured items, untouched by premium modifiers or block discounts.
228	const policyCapOf = (insuredItems: readonly Item[]): number =>
229	  sumOf(insuredItems, itemInsuranceValueOf) * CAP_FACTOR;
230	
231	const entitledPayoutOf = (
232	  incident: Incident,
233	  insuredItems: readonly Item[],
234	): number =>
235	  sumOf(incident.damages, (damage) => damagePayoutOf(damage, insuredItems));
236	
237	// Payouts round down and premiums round up: both in the MHPCO's favour.
238	const roundedPayoutInMHPCOsFavour = (payout: number): number =>
239	  Math.floor(payout);
240	
241	// The cap limits what a policy pays out over its lifetime, so a claim never
242	// pays more than the cap left at the time it is made.
243	const cappedBy = (entitledPayout: number, remainingCap: number): number =>
244	  Math.min(entitledPayout, remainingCap);
245	
246	const claimResultOf = (
247	  step: ClaimStep,
248	  policies: readonly QuoteStep[],
249	  remainingCap: number,
250	): ClaimResult => {
251	  const entitledPayout = entitledPayoutOf(
252	    step.incident,
253	    policies[step.policy].items,
254	  );
255	  const payout = roundedPayoutInMHPCOsFavour(
256	    cappedBy(entitledPayout, remainingCap),
257	  );
258	
259	  return { payout, remainingCap: remainingCap - payout };
260	};
261	
262	const quoteResultOf = (
263	  step: QuoteStep,
264	  customer: Customer,
265	  previousQuoteSteps: readonly QuoteStep[],
266	): QuoteResult => ({
267	  premium: quotePremiumOf(step.items, customer, previousQuoteSteps.length),
268	});
269	
270	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
271	
272	const quoteStepsOf = (steps: readonly Step[]): readonly QuoteStep[] =>
273	  steps.filter(isQuoteStep);
274	
275	const quoteStepsBefore = (
276	  steps: readonly Step[],
277	  stepIndex: number,
278	): readonly QuoteStep[] => quoteStepsOf(steps.slice(0, stepIndex));
279	
280	// The state a scenario carries from one step to the next: the results produced
281	// so far, and how much of each policy's cap is still available.
282	interface ScenarioState {
283	  readonly results: readonly StepResult[];
284	  readonly remainingCaps: readonly number[];
285	}
286	
287	const initialStateOf = (policies: readonly QuoteStep[]): ScenarioState => ({
288	  results: [],
289	  remainingCaps: policies.map((policy) => policyCapOf(policy.items)),
290	});
291	
292	const capsAfterClaim = (
293	  remainingCaps: readonly number[],
294	  policy: number,
295	  remainingCap: number,
296	): readonly number[] =>
297	  remainingCaps.map((cap, index) => (index === policy ? remainingCap : cap));
298	
299	const stateAfterQuote = (
300	  state: ScenarioState,
301	  result: QuoteResult,
302	): ScenarioState => ({ ...state, results: [...state.results, result] });
303	
304	const stateAfterClaim = (
305	  state: ScenarioState,
306	  step: ClaimStep,
307	  result: ClaimResult,
308	): ScenarioState => ({
309	  results: [...state.results, result],
310	  remainingCaps: capsAfterClaim(
311	    state.remainingCaps,
312	    step.policy,
313	    result.remainingCap,
314	  ),
315	});
316	
317	export const runScenario = (scenario: Scenario): ScenarioResult => {
318	  const policies = quoteStepsOf(scenario.steps);
319	
320	  const { results } = scenario.steps.reduce(
321	    (state, step, stepIndex) =>
322	      isQuoteStep(step)
323	        ? stateAfterQuote(
324	            state,
325	            quoteResultOf(
326	              step,
327	              scenario.customer,
328	              quoteStepsBefore(scenario.steps, stepIndex),
329	            ),
330	          )
331	        : stateAfterClaim(
332	            state,
333	            step,
334	            claimResultOf(step, policies, state.remainingCaps[step.policy]),
335	          ),
336	    initialStateOf(policies),
337	  );
338	
339	  return { results };
340	};
